import { PlayerClass, ElementType } from './types';

export type NodeType = 'root' | 'minor' | 'notable' | 'keystone';

/**
 * Path of Exile-style modifier grouping for the percentage-style stats in `stats`
 * (moveSpeed, pickupRadius, damageBonus, expMultiplier — the flat stats maxHp/defense/
 * tierLuck aren't affected by this, see MetaProgression.getPassiveTiersForClass()):
 * - 'increased': pools additively with every other 'increased' node on the same stat
 *   before being applied once (e.g. +30% and +20% increased combine to +50%, not two
 *   separate multiplications).
 * - 'more': its own separate multiplicative layer, stacking with OTHER 'more' modifiers
 *   (and with the combined 'increased' pool) by multiplying rather than adding.
 * Omitted = 'increased', which is every node that existed before this field was added —
 * that default is what keeps the whole pre-existing tree's numbers unchanged.
 */
export type StatModType = 'increased' | 'more';

export interface SkillTreeNode {
  id: string;
  name: string;
  nameTh?: string; // Thai display name — falls back to `name` when missing. See getNodeName().
  type: NodeType;
  classType: PlayerClass | 'universal';
  icon: string;
  cost: number;
  x: number;
  y: number;
  connections: string[]; // IDs of connected neighbor nodes
  description: string;
  descriptionTh?: string; // Plain-language Thai description — falls back to `description` when missing.
  element?: ElementType;
  stats?: {
    maxHp?: number;
    defense?: number;
    moveSpeed?: number;
    pickupRadius?: number;
    damageBonus?: number;
    expMultiplier?: number;
    tierLuck?: number; // % shift toward rarer (S/A) level-up cards, see getTierWeight()
    // Base access to the Reroll/Banish/Lock potions — these start at 0 (ServerPlayer.ts) and
    // are only usable once a node grants them, same additive pool a Trial Quest reward can also
    // add to (see MetaProgression.getPassiveTiersForClass()).
    extraRerolls?: number;
    extraBanishes?: number;
    extraLocks?: number;
  };
  /** Defaults to 'increased' when omitted — see the StatModType doc comment above. */
  modType?: StatModType;
  signatureSkillId?: string; // Maps to signature ability in TRAIT_POOL
  /**
   * Prototype: marks a node as one of the baseline bonuses every hero could plausibly get
   * (HP, move speed, pickup radius, EXP), spliced directly into a class's own branch path
   * instead of being siloed in the separate 'universal' tree. Purely a display flag for now
   * (distinct ring color + tooltip tag) — mechanically it's still just a normal node.
   */
  isUniversalBasic?: boolean;
}

/** A floating label marking one branch's cluster of nodes — purely visual, no gameplay effect. */
export interface SkillCategoryLabel {
  label: string;
  labelTh?: string;
  x: number;
  y: number;
  color?: string; // Defaults to the tree's theme color when omitted.
}

export interface ClassSkillTree {
  classType: PlayerClass | 'universal';
  title: string;
  titleTh?: string;
  elementTitle: string;
  elementTitleTh?: string;
  rootId: string;
  categories?: SkillCategoryLabel[]; // Prototype: see getNodeName() usage sites for how it's rendered.
  nodes: Record<string, SkillTreeNode>;
}

/** Picks a skill tree node's display name for the given language, falling back to English. */
export function getNodeName(node: SkillTreeNode, lang: 'th' | 'en'): string {
  return lang === 'th' && node.nameTh ? node.nameTh : node.name;
}

/** Picks a skill tree node's display description for the given language, falling back to English. */
export function getNodeDescription(node: SkillTreeNode, lang: 'th' | 'en'): string {
  return lang === 'th' && node.descriptionTh ? node.descriptionTh : node.description;
}

